def _gbm(x):
    """Gradient-boosted trees (fit on round3_a + round2_a), flat node arrays; F < 0 marks a leaf."""
    F, T, L, R, V = G_F, G_T, G_L, G_R, G_V
    p = G_BASE
    for i in G_ROOTS:
        f = F[i]
        while f >= 0:
            i = L[i] if x[f] <= T[i] else R[i]
            f = F[i]
        p += V[i]
    return p


